/* ------------------------------------------------------------------ *
 * The artefact catalogue
 * ------------------------------------------------------------------ */

export type ArtefactId =
  | 'shadowing'
  | 'enhancement'
  | 'reverberation'
  | 'ringdown'
  | 'mirror'
  | 'refraction'
  | 'speed'
  | 'sidelobe'
  | 'gratinglobe'
  | 'beamwidth'
  | 'slicethickness'
  | 'rangeambiguity'
  | 'speckle'
  | 'anisotropy'
  | 'aliasing'
  | 'blooming'
  | 'flash'
  | 'twinkle'

type ArtefactEntry = {
  id: ArtefactId
  name: string
  group: string
  /** The physical situation on the stage. */
  setup: string
  /** What the sound actually did. */
  mechanism: string
  /** The machine assumption that was violated. */
  assumption: string
  /** How to recognise it on the image. */
  recognition: string
  /** How to remove it — or exploit it. */
  fix: string
  /** The examination wording that catches people. */
  trap: string
  sceneKind: ArtefactSceneKind
  deltas: Delta[]
}

